class SQLiteState:

    def __init__(self, path: str):
        self.path = path
        # R49: one priority writer owns the main SQLite connection.  Callers never
        # race each other for a raw writer mutex; interactive work is ordered ahead
        # of reminders/schedulers/maintenance.  Reads keep their independent WAL
        # query-only connection.
        self.lock = R25TracedRLock('sqlite-writer-internal')
        self.conn = sqlite3.connect(path, check_same_thread=False, timeout=1.5)
        self.conn.row_factory = sqlite3.Row
        self.read_lock = R25TracedRLock('sqlite-read-admin')
        self.read_conn = None  # compatibility handle; OCH12 reads use thread-local connections
        self._read_tls = threading.local()
        self._read_generation = 0
        # OCH12.16 RAM: readers remain thread-local (no hot-path read lock), but their
        # private SQLite page cache is deliberately small and mmap is disabled.
        # The old 2 MB cache + 32 MB mmap per long-lived worker made RSS grow as
        # more worker lanes touched SQLite.
        self._reader_stats_lock = threading.Lock()
        self._reader_threads_seen = set()
        self._reader_connections_created = 0
        self._init_db()
        self._open_reader()
        self._writer_cv = threading.Condition(threading.RLock())
        self._writer_heap = []
        self._writer_seq = 0
        self._writer_stop = False
        self._writer_ident = None
        self._writer_stats = {'submitted': 0, 'done': 0, 'failed': 0, 'max_pending': 0, 'last_wait_ms': 0.0}
        # OCH12.18 RAM: create the priority writer only on the first real write.
        self._writer_thread = None
        self._writer_start_lock = threading.Lock()
        # R70: one physical online backup for concurrent snapshot consumers.
        # A waiter may reuse only a snapshot completed AFTER its own request began,
        # so sequential later requests never receive a stale image.
        self._backup_coalesce_lock = threading.Lock()
        _snap_tag = hashlib.sha1(os.path.abspath(self.path).encode('utf-8','ignore')).hexdigest()[:12]
        self._backup_cache_path = os.path.join(tempfile.gettempdir(), f'vys262_r70_snapshot_{_snap_tag}.sqlite3')
        self._backup_cache_mono = 0.0
        self._backup_stats = {'physical':0,'reused':0,'last_elapsed':0.0}

    def _writer_priority(self, explicit=None) -> int:
        if explicit is not None:
            try: return max(0, min(9, int(explicit)))
            except Exception: pass
        name = threading.current_thread().name.lower()
        if any(x in name for x in ('fast-ui', 'start-ui', 'callback', 'content', 'ui-')):
            return 0
        if 'webhook' in name or 'request' in name:
            return 1
        if 'reminder' in name:
            return 3
        if 'scheduler' in name or 'background' in name:
            return 4
        if 'maintenance' in name or 'backup' in name or 'snapshot' in name:
            return 5
        return 2

    def _writer_loop(self):
        import heapq as _heapq
        self._writer_ident = threading.get_ident()
        while True:
            with self._writer_cv:
                while not self._writer_heap and not self._writer_stop:
                    self._writer_cv.wait(timeout=1.0)
                if self._writer_stop and not self._writer_heap:
                    return
                _prio, _seq, task = _heapq.heappop(self._writer_heap)
            started = time.monotonic()
            try:
                task['result'] = task['fn'](self.conn)
                self.conn.commit()
                task['ok'] = True
            except Exception as exc:
                try: self.conn.rollback()
                except Exception: pass
                task['error'] = exc
                self._writer_stats['failed'] += 1
            finally:
                task['done_at'] = time.monotonic()
                self._writer_stats['done'] += 1
                self._writer_stats['last_wait_ms'] = round(max(0.0, started - task['queued_at']) * 1000.0, 3)
                task['event'].set()

    def _ensure_writer_thread(self):
        if self._writer_thread is not None and self._writer_thread.is_alive():
            return
        with self._writer_start_lock:
            if self._writer_thread is None or not self._writer_thread.is_alive():
                self._writer_thread = threading.Thread(target=self._writer_loop, name='sqlite-writer-1', daemon=True)
                self._writer_thread.start()

    def _write(self, fn, *, priority=None, timeout=30.0):
        # Re-entrant calls from the writer itself stay direct and never deadlock.
        if threading.get_ident() == self._writer_ident:
            result = fn(self.conn)
            self.conn.commit()
            return result
        if str(os.getenv('FINALIZATION_STARTUP_SMOKE','0') or '0').lower() in {'1','true','yes','on'}:
            result = fn(self.conn); self.conn.commit(); return result
        self._ensure_writer_thread()
        if self._writer_thread is None or not self._writer_thread.is_alive():
            raise RuntimeError('R49 SQLite writer thread is not alive')
        import heapq as _heapq
        ev = threading.Event()
        task = {'fn': fn, 'event': ev, 'queued_at': time.monotonic(), 'ok': False, 'result': None, 'error': None}
        with self._writer_cv:
            self._writer_seq += 1
            _heapq.heappush(self._writer_heap, (self._writer_priority(priority), self._writer_seq, task))
            self._writer_stats['submitted'] += 1
            self._writer_stats['max_pending'] = max(int(self._writer_stats.get('max_pending') or 0), len(self._writer_heap))
            self._writer_cv.notify()
        if not ev.wait(max(1.0, float(timeout or 30.0))):
            raise TimeoutError('SQLite priority writer timeout')
        if task.get('error') is not None:
            raise task['error']
        return task.get('result')

    def writer_status(self) -> dict:
        with self._writer_cv:
            out = dict(self._writer_stats)
            out['pending'] = len(self._writer_heap)
            out['alive'] = bool(self._writer_thread is not None and self._writer_thread.is_alive())
            return out

    def _init_db(self):
        with self.lock:
            cur = self.conn.cursor()
            cur.execute('PRAGMA journal_mode=WAL')
            cur.execute('PRAGMA busy_timeout=1500')
            cur.execute('PRAGMA synchronous=NORMAL')
            cur.execute('PRAGMA temp_store=FILE')
            cur.execute('PRAGMA cache_size=-4096')
            cur.execute('PRAGMA mmap_size=0')
            cur.execute('PRAGMA foreign_keys=ON')
            cur.execute('CREATE TABLE IF NOT EXISTS kv (k TEXT PRIMARY KEY, v TEXT NOT NULL)')
            cur.execute('CREATE TABLE IF NOT EXISTS chats (chat_id TEXT PRIMARY KEY, v TEXT NOT NULL)')
            cur.execute('CREATE TABLE IF NOT EXISTS meta (kind TEXT NOT NULL, k TEXT NOT NULL, v TEXT NOT NULL, PRIMARY KEY(kind, k))')
            cur.execute("CREATE TABLE IF NOT EXISTS cold_fields (chat_id TEXT NOT NULL, k TEXT NOT NULL, v TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT '', PRIMARY KEY(chat_id, k))")
            self.conn.commit()

    def _new_reader_v111(self):
        conn = sqlite3.connect(self.path, check_same_thread=False, timeout=1.5)
        conn.row_factory = sqlite3.Row
        try:
            cache_kb = max(128, min(2048, int(os.getenv('SQLITE_READER_CACHE_KB', '384') or '384')))
        except Exception:
            cache_kb = 384
        try:
            mmap_mb = max(0, min(16, int(os.getenv('SQLITE_READER_MMAP_MB', '0') or '0')))
        except Exception:
            mmap_mb = 0
        try:
            conn.execute('PRAGMA busy_timeout=1500')
            conn.execute('PRAGMA query_only=ON')
            conn.execute(f'PRAGMA cache_size=-{cache_kb}')
            conn.execute(f'PRAGMA mmap_size={mmap_mb * 1024 * 1024}')
        except Exception:
            pass
        try:
            with self._reader_stats_lock:
                self._reader_connections_created += 1
                self._reader_threads_seen.add(int(threading.get_ident()))
        except Exception:
            pass
        return conn

    def reader_status(self) -> dict:
        try:
            with self._reader_stats_lock:
                created = int(self._reader_connections_created or 0)
                threads_seen = len(self._reader_threads_seen)
        except Exception:
            created = 0; threads_seen = 0
        try:
            cache_kb = max(128, min(2048, int(os.getenv('SQLITE_READER_CACHE_KB', '384') or '384')))
        except Exception:
            cache_kb = 384
        try:
            mmap_mb = max(0, min(16, int(os.getenv('SQLITE_READER_MMAP_MB', '0') or '0')))
        except Exception:
            mmap_mb = 0
        return {'connections_created': created, 'threads_seen': threads_seen, 'generation': int(self._read_generation or 0), 'cache_kb_each': cache_kb, 'mmap_mb_each': mmap_mb}

    def _open_reader(self):
        """OCH12: invalidate thread-local WAL readers after DB replacement."""
        with self.read_lock:
            self._read_generation = int(self._read_generation or 0) + 1
            old = getattr(self._read_tls, 'conn', None)
            if old is not None:
                try: old.close()
                except Exception: pass
            self._read_tls.conn = self._new_reader_v111()
            self._read_tls.generation = self._read_generation
            self.read_conn = self._read_tls.conn

    def _reader_v111(self):
        conn = getattr(self._read_tls, 'conn', None)
        generation = int(getattr(self._read_tls, 'generation', -1) or -1)
        if conn is None or generation != int(self._read_generation or 0):
            if conn is not None:
                try: conn.close()
                except Exception: pass
            conn = self._new_reader_v111()
            self._read_tls.conn = conn
            self._read_tls.generation = int(self._read_generation or 0)
        return conn

    def _read_one(self, sql: str, params=()):
        return self._reader_v111().execute(sql, tuple(params)).fetchone()

    def _read_all(self, sql: str, params=()):
        return self._reader_v111().execute(sql, tuple(params)).fetchall()

    def _dump(self, obj) -> str:
        return json.dumps(obj, ensure_ascii=False, separators=(',', ':'))

    def _load(self, raw, default=None):
        if raw is None:
            return default
        try:
            return json.loads(raw)
        except Exception:
            return default

    def get_kv(self, key: str, default=None):
        row = self._read_one('SELECT v FROM kv WHERE k=?', (key,))
        return self._load(row[0], default) if row else default

    def set_kv(self, key: str, obj):
        payload = self._dump(obj)
        return self._write(lambda conn: conn.execute('INSERT INTO kv(k,v) VALUES(?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v', (key, payload)).rowcount)

    def load_root(self):
        return self.get_kv('root', None)

    def save_root(self, obj):
        self.set_kv('root', obj)

    def load_chats(self) -> dict:
        # OCH12.18 RAM: stream rows from SQLite. fetchall() temporarily duplicated
        # every raw JSON row in RAM at the same time as the decoded chats dict.
        out = {}
        cur = self._reader_v111().execute('SELECT chat_id, v FROM chats')
        for row in cur:
            val = self._load(row[1], {})
            if isinstance(val, dict):
                out[str(row[0])] = val
        return out

    def save_chats(self, chats: dict):
        chats = chats or {}
        encoded = {str(chat_id): self._dump(payload) for chat_id, payload in chats.items()}
        def _op(conn):
            existing = {str(r[0]) for r in conn.execute('SELECT chat_id FROM chats').fetchall()}
            conn.executemany('INSERT INTO chats(chat_id,v) VALUES(?,?) ON CONFLICT(chat_id) DO UPDATE SET v=excluded.v', list(encoded.items()))
            stale = existing - set(encoded)
            if stale:
                conn.executemany('DELETE FROM chats WHERE chat_id=?', [(k,) for k in stale])
            return len(encoded)
        return self._write(_op)

    def save_chat(self, chat_id, payload: dict):
        """Точечно сохраняет только один изменившийся чат."""
        encoded = self._dump(payload or {})
        return self._write(lambda conn: conn.execute('INSERT INTO chats(chat_id,v) VALUES(?,?) ON CONFLICT(chat_id) DO UPDATE SET v=excluded.v', (str(chat_id), encoded)).rowcount)

    def save_chat_bundle(self, chat_id, payload: dict, cold_items: dict | None=None):
        """R48: persist chat metadata + loaded cold fields in one SQLite commit."""
        encoded = self._dump(payload or {})
        rows = []
        stamp = datetime.now(timezone.utc).isoformat(timespec='seconds')
        for key, obj in (cold_items or {}).items():
            rows.append((str(chat_id), str(key), self._dump(obj), stamp))
        def _op(conn):
            conn.execute('INSERT INTO chats(chat_id,v) VALUES(?,?) ON CONFLICT(chat_id) DO UPDATE SET v=excluded.v', (str(chat_id), encoded))
            if rows:
                conn.executemany('INSERT INTO cold_fields(chat_id,k,v,updated_at) VALUES(?,?,?,?) ON CONFLICT(chat_id,k) DO UPDATE SET v=excluded.v,updated_at=excluded.updated_at', rows)
            return len(rows)
        return self._write(_op, priority=0 if any(x in threading.current_thread().name.lower() for x in ('content','fast-ui','start-ui','callback')) else None)

    def delete_chat(self, chat_id):
        return self._write(lambda conn: conn.execute('DELETE FROM chats WHERE chat_id=?', (str(chat_id),)).rowcount)

    def get_meta(self, kind: str, key: str, default=None):
        row = self._read_one('SELECT v FROM meta WHERE kind=? AND k=?', (kind, key))
        return self._load(row[0], default) if row else default

    def set_meta(self, kind: str, key: str, obj):
        payload = self._dump(obj)
        return self._write(lambda conn: conn.execute('INSERT INTO meta(kind,k,v) VALUES(?,?,?) ON CONFLICT(kind,k) DO UPDATE SET v=excluded.v', (kind, key, payload)).rowcount)

    def get_cold(self, chat_id, key: str, default=None):
        row = self._read_one('SELECT v FROM cold_fields WHERE chat_id=? AND k=?', (str(chat_id), str(key)))
        return self._load(row[0], default) if row else default

    def set_cold(self, chat_id, key: str, obj):
        payload = self._dump(obj)
        stamp = datetime.now(timezone.utc).isoformat(timespec='seconds')
        return self._write(lambda conn: conn.execute('INSERT INTO cold_fields(chat_id,k,v,updated_at) VALUES(?,?,?,?) ON CONFLICT(chat_id,k) DO UPDATE SET v=excluded.v,updated_at=excluded.updated_at', (str(chat_id), str(key), payload, stamp)).rowcount)

    def set_cold_many(self, chat_id, items: dict):
        """R24: persist all loaded cold fields of one chat in one SQLite commit."""
        rows = []
        stamp = datetime.now(timezone.utc).isoformat(timespec='seconds')
        for key, obj in (items or {}).items():
            rows.append((str(chat_id), str(key), self._dump(obj), stamp))
        if not rows:
            return 0
        return self._write(lambda conn: (conn.executemany('INSERT INTO cold_fields(chat_id,k,v,updated_at) VALUES(?,?,?,?) ON CONFLICT(chat_id,k) DO UPDATE SET v=excluded.v,updated_at=excluded.updated_at', rows), len(rows))[1])

    def delete_cold(self, chat_id, key: str):
        return self._write(lambda conn: conn.execute('DELETE FROM cold_fields WHERE chat_id=? AND k=?', (str(chat_id), str(key))).rowcount)

    def cold_count(self, chat_id=None, key: str | None=None) -> int:
        sql = 'SELECT COUNT(*) FROM cold_fields'
        params = []
        where = []
        if chat_id is not None:
            where.append('chat_id=?')
            params.append(str(chat_id))
        if key is not None:
            where.append('k=?')
            params.append(str(key))
        if where:
            sql += ' WHERE ' + ' AND '.join(where)
        row = self._read_one(sql, params)
        return int(row[0] or 0) if row else 0

    def cold_keys_for_chat(self, chat_id) -> list[str]:
        rows = self._read_all('SELECT k FROM cold_fields WHERE chat_id=?', (str(chat_id),))
        return [str(r[0]) for r in rows]

    def cold_chat_ids(self, keys=None) -> list[int]:
        """Return chat IDs that have authoritative low-RAM cold fields.

        Data Constitution must enumerate these rows too: after idle eviction a finance
        chat can legitimately exist only in cold_fields and must not look like data loss.
        """
        params = []
        sql = 'SELECT DISTINCT chat_id FROM cold_fields'
        if keys:
            clean = [str(x) for x in keys if str(x)]
            if clean:
                sql += ' WHERE k IN (' + ','.join(('?' for _ in clean)) + ')'
                params.extend(clean)
        rows = self._read_all(sql, params)
        out = []
        for row in rows:
            try:
                out.append(int(row[0]))
            except Exception:
                pass
        return sorted(set(out))

    def backup_to(self, target_path: str):
        """R70 single-flight online SQLite snapshot.

        Concurrent consumers (Redis/HEAVY/MEGA/diagnostics) share one physical
        SQLite backup.  A cached image is reusable only when it completed after the
        current caller requested its snapshot, which coalesces overlap without
        serving stale data to later sequential requests.
        """
        target_path = str(target_path)
        os.makedirs(os.path.dirname(target_path) or '.', exist_ok=True)
        requested_mono = time.monotonic()
        started = requested_mono
        reused = False
        try: r25_trace_stage('SQLITE_BACKUP_START', emit=False)
        except Exception: pass
        with self._backup_coalesce_lock:
            cache_path = str(self._backup_cache_path)
            if self._backup_cache_mono >= requested_mono and os.path.exists(cache_path):
                shutil.copy2(cache_path, target_path)
                reused = True
                self._backup_stats['reused'] = int(self._backup_stats.get('reused') or 0) + 1
            else:
                tmp_cache = cache_path + f'.tmp.{os.getpid()}.{threading.get_ident()}'
                try:
                    try: os.unlink(tmp_cache)
                    except FileNotFoundError: pass
                    source = sqlite3.connect(self.path, check_same_thread=False, timeout=0.25)
                    dest = sqlite3.connect(tmp_cache, check_same_thread=False, timeout=0.25)
                    try:
                        try: source.execute('PRAGMA busy_timeout=250')
                        except Exception: pass
                        source.backup(dest, pages=max(256, int(os.getenv('SQLITE_SNAPSHOT_PAGES','4096') or '4096')), sleep=max(0.0, float(os.getenv('SQLITE_SNAPSHOT_SLEEP_SEC','0.001') or '0.001')))
                        dest.commit()
                    finally:
                        try: dest.close()
                        except Exception: pass
                        try: source.close()
                        except Exception: pass
                    os.replace(tmp_cache, cache_path)
                    self._backup_cache_mono = time.monotonic()
                    self._backup_stats['physical'] = int(self._backup_stats.get('physical') or 0) + 1
                    shutil.copy2(cache_path, target_path)
                finally:
                    try:
                        if os.path.exists(tmp_cache): os.unlink(tmp_cache)
                    except Exception: pass
        elapsed = max(0.0, time.monotonic() - started)
        self._backup_stats['last_elapsed'] = elapsed
        try:
            if elapsed >= 0.25 or reused:
                _line=f'R70 SQLITE SNAPSHOT path={os.path.basename(target_path)} elapsed={elapsed:.3f}s reused={int(reused)} physical={int(self._backup_stats.get("physical") or 0)} reused_total={int(self._backup_stats.get("reused") or 0)} shared_lock=0'; log_info(_line); r26_diag_trace_line(_line)
            r25_trace_stage('SQLITE_BACKUP_DONE', elapsed, emit=elapsed >= _R25_TRACE_SLOW_LOCK_SEC)
        except Exception: pass
        return target_path

    def replace_database(self, source_path: str):
        """Replace the working DB through the single R49 writer owner."""
        source_path = str(source_path)
        if not os.path.exists(source_path):
            raise FileNotFoundError(source_path)
        def _replace(_conn):
            with self.read_lock:
                self._read_generation = int(self._read_generation or 0) + 1
                try:
                    _local_reader = getattr(self._read_tls, 'conn', None)
                    if _local_reader is not None: _local_reader.close()
                except Exception:
                    pass
                self._read_tls.conn = None
                self.read_conn = None
            try:
                self.conn.close()
            except Exception:
                pass
            for suffix in ('', '-wal', '-shm'):
                try:
                    if os.path.exists(self.path + suffix):
                        os.remove(self.path + suffix)
                except Exception:
                    pass
            shutil.copy2(source_path, self.path)
            self.conn = sqlite3.connect(self.path, check_same_thread=False, timeout=1.5)
            self.conn.row_factory = sqlite3.Row
            self._init_db()
            self._open_reader()
            return True
        return self._write(_replace, priority=0, timeout=60.0)

SQLITE = SQLiteState(DB_FILE)
LOWRAM_ENABLED = _env_bool('LOWRAM_ENABLED', '1')
LOWRAM_COLD_KEYS = {'records', 'daily_records', 'daily_records_by_date', 'ars_records', 'ars_daily_records', 'ars_daily_records_by_date', 'usd_records', 'usd_daily_records', 'usd_daily_records_by_date', 'secret_messages'}
# OCH12.24: until READY, cold finance history must remain SQLite-backed.
# Boot checks/migrations may inspect it transiently, but must not pin every chat in RAM.
_OCH1223_BOOT_COLD_FENCE = True
_OCH1223_BOOT_COLD_KEYS = {'records','daily_records','ars_records','ars_daily_records','usd_records','usd_daily_records'}
LOWRAM_LIST_KEYS = {'records', 'ars_records', 'usd_records', 'secret_messages'}
LOWRAM_DB_REMOTE_DIR_NAME = 'database'
LOWRAM_DB_LATEST_NAME = 'latest_bot_state.sqlite3.gz'
LOWRAM_DB_HISTORY_KEEP = max(2, min(30, int(os.getenv('LOWRAM_DB_HISTORY_KEEP', '6') or '6')))
LOWRAM_LEGACY_GLOBAL_JSON = _env_bool('LOWRAM_LEGACY_GLOBAL_JSON', '0')
_LOWRAM_DB_RESTORED_THIS_BOOT = False
_LOWRAM_DB_RESTORE_DETAIL = ''
_LOWRAM_LOCK = threading.RLock()
_LOWRAM_STATS = {'cold_loads': 0, 'cold_saves': 0, 'cold_evictions': 0, 'db_snapshots': 0, 'db_snapshot_errors': 0, 'db_restores': 0, 'last_snapshot_at': '', 'last_restore_at': '', 'last_error': ''}

def _lowram_default_for_key(key: str):
    return [] if str(key) in LOWRAM_LIST_KEYS else {}

def _lowram_touch(chat_id: int, key: str):
    try:
        _LOWRAM_STATS['last_access'] = now_local().isoformat(timespec='seconds')
        _LOWRAM_STATS['last_chat'] = int(chat_id)
        _LOWRAM_STATS['last_key'] = str(key)
    except Exception:
        pass

class ColdChatStore(dict):
    """dict-compatible chat state with lazy large fields backed by SQLite."""

    def __init__(self, chat_id: int, initial=None):
        super().__init__(initial or {})
        self._chat_id = int(chat_id)
        self._cold_loaded = {k for k in LOWRAM_COLD_KEYS if dict.__contains__(self, k)}

    def _ensure_cold(self, key: str):
        key = str(key)
        if not LOWRAM_ENABLED or key not in LOWRAM_COLD_KEYS:
            return
        if dict.__contains__(self, key):
            _lowram_touch(self._chat_id, key)
            return
        value = SQLITE.get_cold(self._chat_id, key, _lowram_default_for_key(key))
        if value is None:
            value = _lowram_default_for_key(key)
        dict.__setitem__(self, key, value)
        self._cold_loaded.add(key)
        with _LOWRAM_LOCK:
            _LOWRAM_STATS['cold_loads'] += 1
        _lowram_touch(self._chat_id, key)

    def __getitem__(self, key):
        self._ensure_cold(key)
        return dict.__getitem__(self, key)

    def get(self, key, default=None):
        self._ensure_cold(key)
        if dict.__contains__(self, key):
            return dict.get(self, key)
        return default

    def setdefault(self, key, default=None):
        self._ensure_cold(key)
        if dict.__contains__(self, key):
            return dict.__getitem__(self, key)
        if default is None and str(key) in LOWRAM_COLD_KEYS:
            default = _lowram_default_for_key(str(key))
        dict.__setitem__(self, key, default)
        if str(key) in LOWRAM_COLD_KEYS:
            self._cold_loaded.add(str(key))
            _lowram_touch(self._chat_id, str(key))
        return default

    def __setitem__(self, key, value):
        dict.__setitem__(self, key, value)
        if str(key) in LOWRAM_COLD_KEYS:
            self._cold_loaded.add(str(key))
            _lowram_touch(self._chat_id, str(key))

def _lowram_wrap_store(chat_id, store):
    if isinstance(store, ColdChatStore):
        return store
    return ColdChatStore(int(chat_id), store if isinstance(store, dict) else {})

def _lowram_store_meta_payload(store: dict) -> dict:
    return {str(k): v for k, v in dict.items(store) if str(k) not in LOWRAM_COLD_KEYS}

def _lowram_rebuild_daily(records):
    daily = {}
    for rec in records or []:
        if not isinstance(rec, dict):
            continue
        try:
            dk = _record_day_key(rec) if '_record_day_key' in globals() else str(rec.get('day_key') or '')
        except Exception:
            dk = str(rec.get('day_key') or '')
        if dk:
            rec['day_key'] = dk
            daily.setdefault(str(dk), []).append(rec)
    return daily


def _lowram_flush_chat(chat_id: int, store: dict | None=None, evict: bool=False):
    """R48: snapshot LOW-RAM state only; never perform SQLite I/O here.

    Callers may invoke this while holding chat_lock, so this function must be CPU/RAM-only.
    It returns (meta_payload, cold_batch) for one later SQLite bundle commit.
    """
    if not LOWRAM_ENABLED:
        return ({}, {})
    try:
        cid = int(chat_id)
    except Exception:
        return ({}, {})
    store = store if isinstance(store, dict) else (data.get('chats', {}) or {}).get(str(cid)) if isinstance(data, dict) else None
    if not isinstance(store, dict):
        return ({}, {})
    # OCH12.24: during BOOT a diagnostic/migration read of records must not fan out
    # into three additional daily mirrors for every chat.  Existing loaded daily mirrors
    # are kept coherent; after READY the historical behaviour remains unchanged.
    _boot_cold_fence = bool(globals().get('_OCH1223_BOOT_COLD_FENCE', False))
    for rec_key, daily_key in (('records', 'daily_records'), ('ars_records', 'ars_daily_records'), ('usd_records', 'usd_daily_records')):
        if dict.__contains__(store, rec_key):
            if _boot_cold_fence and (not dict.__contains__(store, daily_key)):
                continue
            records = dict.__getitem__(store, rec_key) or []
            daily = _lowram_rebuild_daily(records)
            dict.__setitem__(store, daily_key, daily)
            if isinstance(store, ColdChatStore):
                store._cold_loaded.add(daily_key)
    cold_batch = {key: copy.deepcopy(dict.__getitem__(store, key)) for key in LOWRAM_COLD_KEYS if dict.__contains__(store, key)}
    meta_payload = copy.deepcopy(_lowram_store_meta_payload(store))
    if evict:
        removed = 0
        for key in list(LOWRAM_COLD_KEYS):
            if dict.__contains__(store, key):
                dict.pop(store, key, None)
                removed += 1
        if isinstance(store, ColdChatStore):
            store._cold_loaded.clear()
        if removed:
            with _LOWRAM_LOCK:
                _LOWRAM_STATS['cold_evictions'] += 1
    return (meta_payload, cold_batch)


def _och1223_boot_evict_all_cold(reason: str='boot_finalize') -> dict:
    """Drop boot-faulted cold ledgers from Python RAM without rewriting SQLite.

    Restore already made SQLite authoritative.  This is intentionally a RAM-only eviction:
    never serialize the materialized lists again just because a boot verifier inspected them.
    """
    removed = 0
    chats = 0
    try:
        for _cid, store in list((data.get('chats', {}) or {}).items()):
            if not isinstance(store, ColdChatStore):
                continue
            one = 0
            for key in tuple(globals().get('_OCH1223_BOOT_COLD_KEYS') or LOWRAM_COLD_KEYS):
                if dict.__contains__(store, key):
                    dict.pop(store, key, None)
                    one += 1
            if one:
                chats += 1
                removed += one
                try:
                    store._cold_loaded.difference_update(globals().get('_OCH1223_BOOT_COLD_KEYS') or LOWRAM_COLD_KEYS)
                except Exception:
                    pass
        if removed:
            with _LOWRAM_LOCK:
                _LOWRAM_STATS['cold_evictions'] += int(removed)
    except Exception as exc:
        try: log_error(f'OCH12.24 boot cold eviction: {exc}')
        except Exception: pass
    trim = {'gc':0,'malloc_trim':False}
    try:
        import gc as _gc
        trim['gc'] = int(_gc.collect() or 0)
    except Exception:
        pass
    try:
        fn = globals().get('memory_malloc_trim')
        if callable(fn):
            trim['malloc_trim'] = bool(fn())
        else:
            import ctypes as _ctypes
            libc = _ctypes.CDLL(None)
            mt = getattr(libc,'malloc_trim',None)
            if mt is not None:
                mt.argtypes=[_ctypes.c_size_t]; mt.restype=_ctypes.c_int
                trim['malloc_trim']=bool(mt(0))
    except Exception:
        pass
    try:
        runtime_event('och1223_boot_cold_evict', f'reason={reason}; fields={removed}; chats={chats}; trim={trim}', 'INFO')
    except Exception:
        pass
    return {'fields':removed,'chats':chats,'trim':trim}


def _lowram_memory_snapshot() -> dict:
    """Small, dependency-safe RAM snapshot used by LOW-RAM cleanup.

    The runtime watcher helper is defined later in the file, so resolve it dynamically.
    This avoids the v114/v115 NameError that disabled post-update GC and flooded the journal.
    """
    for name in ('_runtime_memory_stats', '_memory_usage_snapshot'):
        fn = globals().get(name)
        if callable(fn):
            try:
                snap = fn()
                if isinstance(snap, dict):
                    return snap
            except Exception:
                pass
    return {}


def _lowram_release_chat(chat_id):
    """R48: short snapshot under chat_lock, SQLite bundle after the lock is released."""
    if not LOWRAM_ENABLED or chat_id is None:
        return
    try:
        cid = int(chat_id)
        meta_payload = None; cold_batch = None
        with locked_chat(cid):
            store = (data.get('chats', {}) or {}).get(str(cid)) if isinstance(data, dict) else None
            if isinstance(store, dict):
                meta_payload, cold_batch = _lowram_flush_chat(cid, store, evict=True)
        if meta_payload is not None:
            saved = SQLITE.save_chat_bundle(cid, meta_payload, cold_batch or {})
            with _LOWRAM_LOCK:
                _LOWRAM_STATS['cold_saves'] += int(saved or 0)
        if _lowram_memory_snapshot().get('rss_mb', 0) >= 320:
            import gc
            gc.collect()
    except Exception as exc:
        with _LOWRAM_LOCK:
            _LOWRAM_STATS['last_error'] = str(exc)[:300]
        log_error(f'LOWRAM release chat={chat_id}: {exc}')


def _lowram_prepare_loaded_data(d: dict, migrate_existing: bool=True) -> dict:
    if not LOWRAM_ENABLED or not isinstance(d, dict):
        return d
    chats = d.setdefault('chats', {})
    for cid_s, raw in list(chats.items()):
        try:
            cid = int(cid_s)
        except Exception:
            continue
        raw = raw if isinstance(raw, dict) else {}
        if migrate_existing:
            for key in LOWRAM_COLD_KEYS:
                if key in raw:
                    SQLITE.set_cold(cid, key, raw.get(key))
                    raw.pop(key, None)
        chats[str(cid)] = _lowram_wrap_store(cid, raw)
    return d

def _lowram_materialize_chat_snapshot(chat_id: int, store: dict | None=None) -> dict:
    """Plain JSON-ready chat snapshot. Loads only one chat's cold fields at a time."""
    cid = int(chat_id)
    store = store if isinstance(store, dict) else (data.get('chats', {}) or {}).get(str(cid)) or {}
    snap = _lowram_store_meta_payload(store)
    for key in LOWRAM_COLD_KEYS:
        if dict.__contains__(store, key):
            value = dict.__getitem__(store, key)
        else:
            value = SQLITE.get_cold(cid, key, _lowram_default_for_key(key))
        if value not in (None, [], {}):
            snap[key] = value
    return snap


def _lowram_flush_all_hot(evict: bool=False):
    if not LOWRAM_ENABLED or not isinstance(data, dict):
        return
    with data_lock:
        chat_ids = list(((data.get('chats', {}) or {}).keys()))
        root_snapshot = copy.deepcopy(_sqlite_pack_root(data))
    bundles = []
    for cid_s in chat_ids:
        try: cid = int(cid_s)
        except Exception: continue
        with locked_chat(cid):
            store = ((data.get('chats', {}) or {}).get(str(cid)))
            if isinstance(store, dict):
                meta, cold = _lowram_flush_chat(cid, store, evict=evict)
                bundles.append((cid, meta, cold))
    # No global/chat lock while waiting for SQLite.
    total = 0
    for cid, meta, cold in bundles:
        total += int(SQLITE.save_chat_bundle(cid, meta, cold) or 0)
    SQLITE.save_root(root_snapshot)
    if total:
        with _LOWRAM_LOCK:
            _LOWRAM_STATS['cold_saves'] += total


def lowram_status_text() -> str:
    mem = _lowram_memory_snapshot()
    with _LOWRAM_LOCK:
        st = dict(_LOWRAM_STATS)
    loaded = 0
    try:
        for store in ((data or {}).get('chats', {}) or {}).values():
            if isinstance(store, dict):
                loaded += sum((1 for k in LOWRAM_COLD_KEYS if dict.__contains__(store, k)))
    except Exception:
        pass
    return f"LOW-RAM: {('✅ ВКЛ' if LOWRAM_ENABLED else '⬜ ВЫКЛ')} | RAM {mem.get('rss_mb', '?')} MB\nCold fields loaded now: {loaded}; loads={st.get('cold_loads', 0)} saves={st.get('cold_saves', 0)} evictions={st.get('cold_evictions', 0)}\nSQLite cold rows: {SQLITE.cold_count()} | DB snapshots={st.get('db_snapshots', 0)} restores={st.get('db_restores', 0)}\nПоследний DB snapshot: {st.get('last_snapshot_at') or '—'}; restore: {st.get('last_restore_at') or '—'}\nОшибка: {st.get('last_error') or 'нет'}"

def _sqlite_pack_root(d: dict) -> dict:
    return {k: v for k, v in (d or {}).items() if k != 'chats'}

def _sqlite_unpack_data(root: dict | None, chats: dict | None) -> dict:
    d = default_data()
    if isinstance(root, dict):
        for k, v in root.items():
            d[k] = v
    d['chats'] = chats if isinstance(chats, dict) else {}
    return d

def _import_legacy_global_json_to_db(path: str=DATA_FILE, force: bool=False) -> bool:
    root = SQLITE.load_root()
    chats = SQLITE.load_chats()
    if not force and (root is not None or chats):
        return False
    payload = _load_json(path, None)
    if not isinstance(payload, dict):
        return False
    SQLITE.save_root(_sqlite_pack_root(payload))
    SQLITE.save_chats(payload.get('chats', {}) or {})
    legacy_csv_meta = _load_json(CSV_META_FILE, None)
    if isinstance(legacy_csv_meta, dict):
        SQLITE.set_meta('csv_meta', 'main', legacy_csv_meta)
    legacy_backup_meta = _load_json(CHAT_BACKUP_META_FILE, None)
    if isinstance(legacy_backup_meta, dict):
        SQLITE.set_meta('chat_backup_meta', 'main', legacy_backup_meta)
    return True

def _v177_legacy_0002_log_info(msg: str):
    # OCH12: never block application threads on logging.Handler.lock.
    if not _fast_log_enqueue_v111('INFO', msg):
        try: r26_diag_trace_line('LOG_DROP info ' + str(msg)[:500])
        except Exception: pass
try:
    _v177_legacy_0002_log_info.__name__ = 'log_info'
except Exception:
    pass

def _v177_legacy_0003_log_error(msg: str):
    _fast_log_enqueue_v111('ERROR', msg)
    try:
        if 'bot_journal' in globals():
            bot_journal('error', None, str(msg), 'ERROR')
    except Exception:
        pass
    try:
        with error_log_lock:
            BOT_ERROR_LOG.append({'ts': now_local().strftime('%Y-%m-%d %H:%M:%S') if 'now_local' in globals() else time.strftime('%Y-%m-%d %H:%M:%S'), 'msg': str(msg)[:900]})
    except Exception:
        pass
try:
    _v177_legacy_0003_log_error.__name__ = 'log_error'
except Exception:
    pass

