def _journal_rotate_local_locked() -> None:
    try:
        if not os.path.exists(BOT_JOURNAL_FILE) or os.path.getsize(BOT_JOURNAL_FILE) < BOT_JOURNAL_LOCAL_MAX_BYTES:
            return
        oldest = f'{BOT_JOURNAL_FILE}.{BOT_JOURNAL_LOCAL_KEEP_FILES}'
        try:
            if os.path.exists(oldest):
                os.remove(oldest)
        except Exception:
            pass
        for idx in range(BOT_JOURNAL_LOCAL_KEEP_FILES - 1, 0, -1):
            src = f'{BOT_JOURNAL_FILE}.{idx}'
            dst = f'{BOT_JOURNAL_FILE}.{idx + 1}'
            if os.path.exists(src):
                try:
                    os.replace(src, dst)
                except Exception:
                    pass
        try:
            os.replace(BOT_JOURNAL_FILE, f'{BOT_JOURNAL_FILE}.1')
        except Exception:
            pass
    except Exception:
        pass

def _journal_write_row(row: dict):
    try:
        line = json.dumps(row, ensure_ascii=False, separators=(',', ':')) + '\n'
        os.makedirs(os.path.dirname(os.path.abspath(BOT_JOURNAL_FILE)) or '.', exist_ok=True)
        with _JOURNAL_FILE_LOCK:
            _journal_rotate_local_locked()
            with open(BOT_JOURNAL_FILE, 'a', encoding='utf-8') as jf:
                jf.write(line)
    except Exception:
        pass

def _journal_write_rows_batch_v214(rows):
    if not rows:
        return
    try:
        payload = ''.join(json.dumps(row, ensure_ascii=False, separators=(',', ':')) + '\n' for row in rows)
        os.makedirs(os.path.dirname(os.path.abspath(BOT_JOURNAL_FILE)) or '.', exist_ok=True)
        with _JOURNAL_FILE_LOCK:
            _journal_rotate_local_locked()
            with open(BOT_JOURNAL_FILE, 'a', encoding='utf-8') as jf:
                jf.write(payload)
    except Exception:
        # Local forensic journal is best-effort; never recurse through bot_journal here.
        pass

def _journal_file_drain_v214():
    global _JOURNAL_FILE_DRAIN_SCHEDULED
    while True:
        with _JOURNAL_FILE_PENDING_LOCK:
            if not _JOURNAL_FILE_PENDING:
                _JOURNAL_FILE_DRAIN_SCHEDULED = False
                return
            batch = []
            for _ in range(min(256, len(_JOURNAL_FILE_PENDING))):
                batch.append(_JOURNAL_FILE_PENDING.popleft())
        _journal_write_rows_batch_v214(batch)

def _journal_enqueue_file_v214(row: dict) -> bool:
    global _JOURNAL_FILE_DRAIN_SCHEDULED, _JOURNAL_FILE_DROPPED
    need_submit = False
    with _JOURNAL_FILE_PENDING_LOCK:
        while len(_JOURNAL_FILE_PENDING) >= int(BOT_JOURNAL_FILE_PENDING_MAX):
            _JOURNAL_FILE_PENDING.popleft()
            _JOURNAL_FILE_DROPPED += 1
        _JOURNAL_FILE_PENDING.append(dict(row))
        if not _JOURNAL_FILE_DRAIN_SCHEDULED:
            _JOURNAL_FILE_DRAIN_SCHEDULED = True
            need_submit = True
    if not need_submit:
        return True
    try:
        if JOURNAL_TASK_POOL.submit_unique('journal-file-drain-v214', _journal_file_drain_v214):
            return True
    except Exception:
        pass
    # If the tiny journal lane is unavailable, release the scheduled flag.  The next
    # row will retry; keep the row buffered rather than executing disk IO in hot path.
    with _JOURNAL_FILE_PENDING_LOCK:
        _JOURNAL_FILE_DRAIN_SCHEDULED = False
    return False

def _v177_legacy_0006_bot_journal(action: str, chat_id=None, detail: str='', level: str='INFO'):
    """Пишет действие в общий журнал: команды, кнопки, функции, Telegram API, backup, ошибки."""
    try:
        action_name = str(action or '')
        always_record = action_name.startswith('window_')
        if not always_record and action_name not in {'journal_toggle', 'journal_chat_toggle', 'journal_export_requested'} and (str(level or 'INFO').upper() != 'ERROR'):
            if not journal_should_record(chat_id):
                return None
        _ws = WEBHOOK_TASK_POOL.stats()
        _uis = UI_TASK_POOL.stats() if 'UI_TASK_POOL' in globals() else {}
        _fs = FINANCE_TASK_POOL.stats()
        _fws = FORWARD_TASK_POOL.stats()
        _ds = DELTA_TASK_POOL.stats() if 'DELTA_TASK_POOL' in globals() else {}
        row = {'ts': _journal_ts(), 'level': str(level or 'INFO'), 'action': str(action or '')[:160], 'chat_id': str(chat_id) if chat_id is not None else '', 'chat_name': '', 'detail': str(detail or '')[:3000], 'thread': threading.current_thread().name, 'profile': active_bot_behavior_profile() if 'data' in globals() and isinstance(data, dict) else 'startup', 'bot_version': str(globals().get('VERSION') or 'startup'), 'render_commit': str(os.getenv('RENDER_GIT_COMMIT', '') or ''), 'webhook_pending': _ws.get('pending', 0), 'webhook_active': _ws.get('active', 0), 'ui_pending': _uis.get('pending', 0), 'ui_active': _uis.get('active', 0), 'finance_pending': _fs.get('pending', 0), 'finance_active': _fs.get('active', 0), 'forward_pending': _fws.get('pending', 0), 'forward_active': _fws.get('active', 0), 'delta_pending': _ds.get('pending', 0), 'general_pending': GENERAL_TASK_POOL.stats().get('pending', 0), 'backup_pending': BACKUP_TASK_POOL.stats().get('pending', 0), 'runtime_phase': str((globals().get('_RUNTIME_STATE') or {}).get('phase') or ''), 'runtime_ready': bool((globals().get('_RUNTIME_STATE') or {}).get('ready', False)), 'boot_id': _JOURNAL_BOOT_ID, 'pid': os.getpid()}
        # OCH12: journal metadata may not contend with live UI for data/chat state.
        # Name resolution is optional and disabled by default; chat_id remains canonical.
        try:
            if chat_id is not None and str(os.getenv('JOURNAL_RESOLVE_CHAT_NAME','0') or '0').lower() in {'1','true','yes','on'}:
                row['chat_name'] = get_chat_display_name(int(chat_id))
        except Exception:
            pass
        with bot_journal_lock:
            BOT_ACTION_LOG.append(row)
        _critical_action = action_name.startswith(('runtime_shutdown_', 'runtime_fatal_', 'runtime_thread_unhandled_exception'))
        _critical_remote = BOT_CRITICAL_JOURNAL_DURABLE_ENABLED and (str(level or 'INFO').upper() in {'ERROR', 'CRITICAL'} or _critical_action)
        if BOT_JOURNAL_DURABLE_ENABLED or _critical_remote:
            try:
                _copy = dict(row)
                _copy['critical_remote'] = bool(_critical_remote)
                _buffer_len = 0
                with _JOURNAL_DURABLE_LOCK:
                    _JOURNAL_DURABLE_BUFFER.append(_copy)
                    _buffer_len = len(_JOURNAL_DURABLE_BUFFER)
                if _buffer_len >= BOT_JOURNAL_DURABLE_FLUSH_ROWS and journal_compact_remote_enabled():
                    sched = globals().get('DELAYED_SCHEDULER')
                    flush_fn = globals().get('journal_flush_to_mega')
                    if sched is not None and callable(flush_fn):
                        sched.schedule('journal-size-flush', 1.0, flush_fn, True)
            except Exception:
                pass
        _journal_enqueue_file_v214(row)
        if str(level or '').upper() in {'ERROR', 'CRITICAL'}:
            try:
                flush_fn = globals().get('journal_flush_to_mega')
                scheduler = globals().get('DELAYED_SCHEDULER')
                if callable(flush_fn) and scheduler is not None and _journal_should_accelerate_error_flush(action_name, chat_id, level, detail):
                    scheduler.schedule('journal-error-flush', 5.0, flush_fn, True)
            except Exception:
                pass
        return row
    except Exception:
        return None
