def build_forward_status_text(title: str | None=None) -> str:
    lines = []
    if title:
        lines.append(title)
        lines.append('')
    if title and 'Пересылка' in str(title):
        lines.append('Шаги: 1) выберите чат A → 2) выберите чат B → 3) включите 📨 пересылку и 💰 финучёт пересылки по нужным направлениям.')
        lines.append('')
    lines.append('Текущие связи:')
    lines.extend(build_forward_status_lines())
    # R70: visual rules are not enough.  Show whether the production resolver
    # would actually route messages now (mode/status/tenant/suspension included).
    try:
        pair_fn = globals().get('collect_forward_pairs_for_menu')
        resolver = globals().get('resolve_forward_targets')
        pairs = list(pair_fn() or []) if callable(pair_fn) else []
        blocked=[]; active=0
        if callable(resolver):
            for a,b in pairs:
                ab = int(b) in {int(x) for x in (resolver(int(a)) or [])}
                ba = int(a) in {int(x) for x in (resolver(int(b)) or [])}
                active += int(ab) + int(ba)
                if not ab and not ba:
                    blocked.append((int(a),int(b)))
        if pairs:
            lines.append('')
            lines.append(f'Runtime-маршруты: ✅ {active} направлений · ⚠️ полностью заблокированных пар {len(blocked)}')
            for a,b in blocked[:6]:
                lines.append(f'⚠️ {chat_button_title(a)} ↔ {chat_button_title(b)}: правило есть, но resolve_forward_targets() сейчас не даёт маршрут')
            if len(blocked)>6:
                lines.append(f'…ещё {len(blocked)-6}')
    except Exception:
        pass
    return '\n'.join(lines)

def _find_forward_origin_by_copied_message(chat_id: int, msg_id: int):
    """
    Ищет origin (source_chat_id, source_msg_id) по копии сообщения в конкретном чате.
    Нужно для правильного reply, когда пользователь отвечает на сообщение,
    которое бот ранее переслал из другого чата.
    """
    try:
        for (src_chat_id, src_msg_id), pairs in forward_map.items():
            for pair_chat_id, pair_msg_id in pairs:
                if int(pair_chat_id) == int(chat_id) and int(pair_msg_id) == int(msg_id):
                    return (int(src_chat_id), int(src_msg_id))
    except Exception:
        pass
    return (None, None)

def resolve_reply_target_message_id(source_chat_id: int, reply_to_message_id: int | None, dst_chat_id: int):
    """
    Возвращает message_id, к которому нужно привязать reply в целевом чате.

    Поддерживает оба сценария:
    1) reply на исходное сообщение текущего чата
    2) reply на сообщение, которое бот переслал сюда из другого чата
    """
    if not reply_to_message_id:
        return None
    source_chat_id = int(source_chat_id)
    dst_chat_id = int(dst_chat_id)
    reply_to_message_id = int(reply_to_message_id)
    try:
        for link_dst_chat_id, link_dst_msg_id in get_forward_links(source_chat_id, reply_to_message_id):
            if int(link_dst_chat_id) == dst_chat_id:
                return int(link_dst_msg_id)
    except Exception:
        pass
    try:
        origin_chat_id, origin_msg_id = _find_forward_origin_by_copied_message(source_chat_id, reply_to_message_id)
        if origin_chat_id is not None and origin_msg_id is not None:
            if dst_chat_id == int(origin_chat_id):
                return int(origin_msg_id)
            for link_dst_chat_id, link_dst_msg_id in get_forward_links(origin_chat_id, origin_msg_id):
                if int(link_dst_chat_id) == dst_chat_id:
                    return int(link_dst_msg_id)
    except Exception:
        pass
    return None
_telegram_send_last_ts = {}
_telegram_send_rate_lock = threading.RLock()
_telegram_global_rate_lock = threading.RLock()
_telegram_global_last_ts = 0.0
_telegram_global_block_until = 0.0
_telegram_guard_local = threading.local()

try:
    TELEGRAM_GLOBAL_MIN_GAP = max(0.05, float(os.getenv('TELEGRAM_GLOBAL_MIN_GAP', '0.075') or '0.075'))
except Exception:
    TELEGRAM_GLOBAL_MIN_GAP = 0.075

def _telegram_retry_after_seconds(err: Exception):
    """Достаёт retry_after из Telegram 429: Too Many Requests."""
    try:
        result_json = getattr(err, 'result_json', None) or {}
        params = result_json.get('parameters') or {}
        if 'retry_after' in params:
            return int(params.get('retry_after') or 0)
    except Exception:
        pass
    text = str(err or '')
    m = re.search('retry after\\s+(\\d+)', text, re.I)
    if m:
        try:
            return int(m.group(1))
        except Exception:
            pass
    return None

def is_telegram_429(err: Exception) -> bool:
    """True если Telegram ограничил частоту. Для UI такие ошибки нельзя держать sleep-ом."""
    try:
        return _telegram_retry_after_seconds(err) is not None
    except Exception:
        return 'too many requests' in str(err or '').lower()

def _is_fast_ui_purpose(purpose: str) -> bool:
    p = str(purpose or '').lower()
    fast_marks = ('safe_edit', 'commander', 'command_window', 'window_switch', 'ui_toggle', 'countdown', 'secret_window', 'secret media', 'secret_edit_debounce', 'category_wait_countdown', 'o9_secret_wait_countdown')
    return any((x in p for x in fast_marks))

def _telegram_rate_limit_chat(chat_id, min_gap: float=0.35):
    """Мягкий лимит отправки в один чат, чтобы реже получать 429 при шквале пересылок."""
    try:
        cid = int(chat_id)
    except Exception:
        return
    with _telegram_send_rate_lock:
        now_ts = time.time()
        prev_ts = float(_telegram_send_last_ts.get(cid, 0) or 0)
        wait = float(min_gap) - (now_ts - prev_ts)
        if wait > 0:
            try: r52_diag('TELEGRAM_CHAT_RATE_WAIT', chat=cid, wait=wait, min_gap=min_gap)
            except Exception: pass
            time.sleep(wait)
        _telegram_send_last_ts[cid] = time.time()

def _telegram_rate_limit_global():
    """R37: single bot-token gate. Respects a shared 429 cooldown across every thread."""
    global _telegram_global_last_ts
    with _telegram_global_rate_lock:
        now_ts = time.time()
        block_wait = max(0.0, float(globals().get('_telegram_global_block_until', 0.0) or 0.0) - now_ts)
        gap_wait = TELEGRAM_GLOBAL_MIN_GAP - (now_ts - _telegram_global_last_ts)
        wait = max(block_wait, gap_wait, 0.0)
        if wait > 0:
            try: r52_diag('TELEGRAM_GLOBAL_RATE_WAIT', wait=wait, block_wait=block_wait, gap_wait=gap_wait, min_gap=TELEGRAM_GLOBAL_MIN_GAP)
            except Exception: pass
            time.sleep(wait)
        _telegram_global_last_ts = time.time()

def _telegram_register_429_cooldown(err: Exception, extra: float=0.35) -> float:
    """R37: one 429 pauses all Telegram callers, not only the thread that was rejected."""
    global _telegram_global_block_until
    retry_after = _telegram_retry_after_seconds(err)
    wait = max(1.0, float(retry_after or 1)) + max(0.1, float(extra))
    with _telegram_global_rate_lock:
        _telegram_global_block_until = max(float(_telegram_global_block_until or 0.0), time.time() + wait)
    return wait

def _tg_first_chat_id(args, kwargs):
    if 'chat_id' in kwargs:
        return kwargs.get('chat_id')
    if args:
        return args[0]
    return None

def _tg_call_retry(func, *args, attempts: int=7, purpose: str='telegram', **kwargs):
    """
    Telegram API wrapper: если Telegram вернул 429, ждём retry_after и повторяем.
    Это нужно, чтобы пересылка не терялась, а доставлялась позже.
    """
    last_err = None
    _r52_tg_call_started=time.monotonic()
    try: r52_diag('TG_CALL_ENTER', purpose=purpose, func=getattr(func,'__name__',str(func))[:120], attempts=attempts, chat=_tg_first_chat_id(args,kwargs))
    except Exception: pass
    for attempt in range(1, int(attempts) + 1):
        try:
            chat_id = _tg_first_chat_id(args, kwargs)
            try: r52_diag('TG_CALL_ATTEMPT', purpose=purpose, func=getattr(func,'__name__',str(func))[:120], attempt=attempt, attempts=attempts, chat=chat_id)
            except Exception: pass
            _telegram_rate_limit_global()
            if chat_id is not None:
                ui_gap = effective_fast_telegram_gap() if _is_fast_ui_purpose(purpose) else 0.35
                _telegram_rate_limit_chat(chat_id, min_gap=ui_gap)
            try:
                if verbose_telegram_journal_enabled() and (not _is_fast_ui_purpose(purpose)):
                    bot_journal('telegram_api_call', chat_id, f"{purpose}: {getattr(func, '__name__', str(func))} attempt={attempt}/{attempts}")
            except Exception:
                pass
            try:
                for _obj in list(args) + list(kwargs.values()):
                    if hasattr(_obj, 'seek'):
                        try:
                            _obj.seek(0)
                        except Exception:
                            pass
            except Exception:
                pass
            try:
                _telegram_guard_local.in_retry = True
                _res = func(*args, **kwargs)
            finally:
                _telegram_guard_local.in_retry = False
            # R48: success is a pure transport hot path. Incoming updates and explicit
            # probes refresh lifecycle; every send/edit must not acquire data_lock.
            try: r52_diag('TG_CALL_OK', purpose=purpose, func=getattr(func,'__name__',str(func))[:120], attempt=attempt, chat=chat_id, elapsed=time.monotonic()-_r52_tg_call_started)
            except Exception: pass
            return _res
        except TypeError:
            raise
        except Exception as e:
            last_err = e
            try: r52_diag('TG_CALL_ERROR', purpose=purpose, func=getattr(func,'__name__',str(func))[:120], attempt=attempt, chat=locals().get('chat_id'), elapsed=time.monotonic()-_r52_tg_call_started, error=f'{type(e).__name__}:{str(e)[:1000]}')
            except Exception: pass
            retry_after = _telegram_retry_after_seconds(e)
            if retry_after is None:
                try:
                    chat_id_for_mark = _tg_first_chat_id(args, kwargs)
                    if chat_id_for_mark is not None and _is_bot_removed_error(e):
                        set_chat_bot_removed(int(chat_id_for_mark), True, str(e)[:240])
                except Exception:
                    pass
                raise
            wait = _telegram_register_429_cooldown(e, extra=0.35)
            log_info(f'[TG 429 RETRY] {purpose}: attempt={attempt}/{attempts}, wait={wait:.2f}s, error={str(e)[:220]}')
            try:
                bot_journal('telegram_429_retry', chat_id if 'chat_id' in locals() else None, f'{purpose}: attempt={attempt}/{attempts}, wait={wait}s, error={str(e)[:220]}', 'WARN')
            except Exception:
                pass
            if _is_fast_ui_purpose(purpose):
                raise e
            if attempt >= int(attempts):
                break
            time.sleep(wait)
    raise last_err


# R37: Guard legacy direct bot.* calls too. Older modules contain direct Telegram calls
# that used to bypass _tg_call_retry and could collectively trigger bot-wide 429s.
_R37_TG_GUARDED_METHODS = (
    'send_message', 'edit_message_text', 'edit_message_caption', 'edit_message_reply_markup',
    'answer_callback_query', 'send_document', 'send_photo', 'send_video', 'send_audio',
    'send_voice', 'send_media_group', 'delete_message', 'copy_message', 'forward_message',
)
_R37_TG_RAW_METHODS = {}

def _r37_direct_chat_id(method_name, args, kwargs):
    if method_name == 'answer_callback_query':
        return None
    if 'chat_id' in kwargs:
        return kwargs.get('chat_id')
    return args[0] if args else None

def _r37_make_guarded_bot_method(method_name, raw):
    def _guarded(*args, **kwargs):
        # Calls originating from _tg_call_retry are already gated/retried there.
        if bool(getattr(_telegram_guard_local, 'in_retry', False)):
            return raw(*args, **kwargs)
        cid = _r37_direct_chat_id(method_name, args, kwargs)
        max_attempts = 2 if method_name not in {'answer_callback_query', 'delete_message'} else 1
        last = None
        for attempt in range(max_attempts):
            _telegram_rate_limit_global()
            if cid is not None:
                _telegram_rate_limit_chat(cid, min_gap=0.36)
            try:
                return raw(*args, **kwargs)
            except Exception as exc:
                last = exc
                if not is_telegram_429(exc):
                    raise
                wait = _telegram_register_429_cooldown(exc, extra=0.35)
                try:
                    log_info(f'[R37 TG GLOBAL 429] method={method_name} wait={wait:.2f}s cid={cid}')
                except Exception:
                    pass
                if attempt + 1 >= max_attempts:
                    raise
                # Shared gate sleeps on the next loop; don't create independent retry storms.
        if last is not None:
            raise last
    try:
        _guarded.__name__ = getattr(raw, '__name__', method_name)
    except Exception:
        pass
    return _guarded

def _r37_install_botwide_telegram_guard():
    for _name in _R37_TG_GUARDED_METHODS:
        _raw = getattr(bot, _name, None)
        if not callable(_raw) or _name in _R37_TG_RAW_METHODS:
            continue
        _R37_TG_RAW_METHODS[_name] = _raw
        setattr(bot, _name, _r37_make_guarded_bot_method(_name, _raw))

_r37_install_botwide_telegram_guard()

def _call_with_optional_reply(send_func, *args, reply_to_message_id=None, **kwargs):
    if reply_to_message_id:
        for extra in ({'reply_to_message_id': int(reply_to_message_id), 'allow_sending_without_reply': True}, {'reply_to_message_id': int(reply_to_message_id)}, {}):
            try:
                return _tg_call_retry(send_func, *args, purpose='send_with_reply', **kwargs, **extra)
            except TypeError:
                continue
    return _tg_call_retry(send_func, *args, purpose='send', **kwargs)

