def _today_finance_total() -> float:
    total = 0.0
    day = today_key()
    for _cid, store in (data.get('chats', {}) or {}).items():
        if not isinstance(store, dict):
            continue
        for rec in (store.get('daily_records', {}) or {}).get(day, []) or []:
            try:
                amount = float(rec.get('amount', 0) or 0)
                if amount < 0:
                    total += abs(amount)
            except Exception:
                pass
    return total

