    if not chats:
        kb.row(IB('Нет чатов с секретами', callback_data='none'))
    kb.row(IB('🔙 Назад осн. окно', callback_data=f'd:{today_key()}:back_main'), IB(_secret_close_label(remaining), callback_data='secclose'))
