    lines = ['👥 ОБЪЕДИНЁННАЯ НАПОМИНАЛКА', '', f'Чат: {get_chat_display_name(int(target_chat_id))}', f'Напоминалок: {len(members)} · активных: {active}', 'Общий ритм при совместной работе: каждые 2 часа.', '']
