def _v177_legacy_0154_remove_forward_finance(src_chat_id: int, dst_chat_id: int):
    ff = data.setdefault('forward_finance', {})
    src = str(src_chat_id)
    dst = str(dst_chat_id)
    if src in ff and dst in ff[src]:
        del ff[src][dst]
    if src in ff and (not ff[src]):
        del ff[src]
