def _v150_migrate_chat_lifecycle() -> int:
    count = 0
    for cid, store in list((data.get('chats') or {}).items()):
        if not isinstance(store, dict):
            continue
        try:
            chat_id = int(cid)
            before = store.get('chat_lifecycle_v150')
            _v150_lifecycle(chat_id)
            if not isinstance(before, dict):
                count += 1
        except Exception:
            continue
    if count:
        save_data(data)
    return count

