    _v157_save_process_settings()
    if not enabled:
        _v157_clear_process_scope(scope)
    try:
        bot_journal('process_visual_scope_toggle', int(OWNER_ID or 0), f'scope={scope}; enabled={int(bool(enabled))}')
    except Exception:
        pass
    return bool(enabled)

