    with _FILE_JOB_LOCK:
        alive = isinstance(_FILE_JOB_STATE.get(key), dict)
    if alive:
        DELAYED_SCHEDULER.schedule(f'file-job-tick:{key}', internal_timer_seconds('process_status_refresh', 10.0), _file_job_tick, key)
