START_UI_TASK_POOL = KeyedTaskPool('start-ui', _env_int('START_UI_WORKERS', 1, 1, 4), _env_int('START_UI_MAX_PENDING', 120, 20, 600))
WINDOW_UI_TASK_POOL = UI_TASK_POOL
