def _v161_schedule_delete(chat_id: int, message_id: int, delay: float, prefix: str='delete') -> None:
    fn = globals().get('_v160_schedule_delete')
    if callable(fn):
        fn(int(chat_id), int(message_id), float(delay), str(prefix or 'delete'))
