            quick2 = [IB('10 мин', callback_data='v213:itmr_input:600'), IB('15 мин', callback_data='v213:itmr_input:900'), IB('30 мин', callback_data='v213:itmr_input:1800')]
            kb.keyboard = [quick1, quick2] + rows
